insert into public.project_challenges (project_id, position, problem, solution) values ((select id from public.projects where slug = 'polypress'), 0, 'Tối ưu hiệu suất và độ trễ kết nối CSDL', 'Tích hợp HikariCP thay vì mở kết nối JDBC truyền thống mỗi lần truy vấn.');
insert into public.project_challenges (project_id, position, problem, solution) values ((select id from public.projects where slug = 'polypress'), 1, 'Nguy cơ tấn công SQL Injection và Memory Leak', 'Áp dụng PreparedStatement đồng bộ cùng khối try-with-resources cho tất cả DAO.');
insert into public.project_challenges (project_id, position, problem, solution) values ((select id from public.projects where slug = 'polypress'), 2, 'Tổ chức mã nguồn giao diện động', 'Ứng dụng JSTL và mô-đun hóa Layout (Header, Footer, Navbar, Admin View).');
