insert into public.projects (slug, title, subtitle, role, started_on, ended_on, summary, github_url, cover_url, video_url, published, position) values ('videostream', 'VideoStream', 'Nền Tảng Giải Trí & Xem Video Trực Tuyến (Java Web & Jakarta EE)', 'Fullstack Developer', '2026-03-01', '2026-04-01', 'Nền tảng web giải trí và xem video trực tuyến theo mô hình MVC với Jakarta EE 10 và Hibernate 6. Hỗ trợ phân quyền truy cập, tương tác yêu thích, chia sẻ video qua email tự động và bảng điều khiển quản trị báo cáo chuyên sâu.', 'https://github.com/ternal-qtri/Online-Entertainment-Website', 'https://res.cloudinary.com/twwukonq/image/upload/v1790263458/ternal_portfolio/projects/ykwi3owslgflnk6jvh5i.png', null, true, 1);
