insert into public.project_features (project_id, position, title, detail) values ((select id from public.projects where slug = 'videostream'), 0, 'Quản lý Video & Tương tác', 'Duyệt danh mục video phân trang, tìm kiếm theo từ khóa, phát video YouTube nhúng, tương tác Like/Unlike và quản lý danh sách yêu thích cá nhân.');
insert into public.project_features (project_id, position, title, detail) values ((select id from public.projects where slug = 'videostream'), 1, 'Chia sẻ Video qua Email', 'Tích hợp Jakarta Mail kết nối SMTP Server cho phép gửi thông tin và đường dẫn video trực tiếp đến danh sách nhiều email bạn bè cùng lúc.');
insert into public.project_features (project_id, position, title, detail) values ((select id from public.projects where slug = 'videostream'), 2, 'Xác thực & Ghi nhớ phiên', 'Hệ thống đăng ký, đăng nhập với tính năng Remember Me qua Cookie kết hợp Session, cùng Filter phân quyền nghiêm ngặt giữa User và Admin.');
insert into public.project_features (project_id, position, title, detail) values ((select id from public.projects where slug = 'videostream'), 3, 'Admin Dashboard & Báo cáo', 'Bảng điều khiển quản trị trực quan thống kê số liệu video/user, Top Favorites, CRUD Video/User và 3 phân hệ báo cáo thống kê chuyên sâu.');
insert into public.project_challenges (project_id, position, problem, solution) values ((select id from public.projects where slug = 'videostream'), 0, 'Đồng bộ trạng thái Like khi duyệt danh sách video', 'Sử dụng trường @Transient trong Entity Video kết hợp FavoriteDAO kiểm tra tương tác của người dùng hiện tại mà không làm biến dạng cấu trúc CSDL.');
insert into public.project_challenges (project_id, position, problem, solution) values ((select id from public.projects where slug = 'videostream'), 1, 'Truy vấn thống kê tổng hợp số lượng Favorites và Users phức tạp', 'Tối ưu hóa bằng các câu lệnh JPQL Projection và Aggregate Functions thay vì xử lý lọc thủ công trên tầng ứng dụng.');
insert into public.project_challenges (project_id, position, problem, solution) values ((select id from public.projects where slug = 'videostream'), 2, 'Trải nghiệm tương tác người dùng mượt mà trên nền JSP', 'Tích hợp thư viện Notyf Toast và SweetAlert2 để xử lý thông báo phản hồi và xác nhận hành động trực quan.');
insert into public.project_lessons (project_id, position, content) values ((select id from public.projects where slug = 'videostream'), 0, 'Nắm vững kiến trúc Jakarta EE 10 trên nền Java 25 kết hợp cấu trúc Generic DAO và mô hình MVC chuẩn mực.');
insert into public.project_lessons (project_id, position, content) values ((select id from public.projects where slug = 'videostream'), 1, 'Thành thạo tích hợp và cấu hình Hibernate Core 6.6 / JPA để ánh xạ quan hệ (ManyToOne, Lazy loading) và xử lý truy vấn JPQL phức tạp (Group By, Count, Join Fetch).');
insert into public.project_lessons (project_id, position, content) values ((select id from public.projects where slug = 'videostream'), 2, 'Làm chủ Filter Chain trong Java Web để kiểm soát luồng xác thực (Authentication Filter) và tự động phục hồi phiên đăng nhập qua Cookie.');
